"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { CircleAlert, CircleCheck, Info, TriangleAlert } from "./icons";

// Toast: generated by UIX from the design system. Same variants and sizes as the Figma component.

const toastVariants = cva(
  "pointer-events-auto flex w-full max-w-[360px] items-center gap-3 px-4 py-3 text-body-medium rounded-lg",
  {
    variants: {
      theme: {
        light: "",
        dark: "",
      },
      type: {
        default: "",
        success: "",
        warning: "",
        error: "",
      },
    },
    compoundVariants: [
      { theme: "light", type: "default", class: "bg-surface border border-line-default text-fg-primary shadow-lg [&_[data-slot=icon]]:text-icon-brand [&_[data-slot=action]]:text-fg-brand" },
      { theme: "light", type: "success", class: "bg-surface border border-line-default text-fg-primary shadow-lg [&_[data-slot=icon]]:text-icon-success [&_[data-slot=action]]:text-fg-brand" },
      { theme: "light", type: "warning", class: "bg-surface border border-line-default text-fg-primary shadow-lg [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=action]]:text-fg-brand" },
      { theme: "light", type: "error", class: "bg-surface border border-line-default text-fg-primary shadow-lg [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=action]]:text-fg-brand" },
      { theme: "dark", type: "default", class: "skin-quiet bg-inverse text-fg-inverse [&_[data-slot=icon]]:text-fg-inverse [&_[data-slot=action]]:text-fg-inverse" },
      { theme: "dark", type: "success", class: "skin-quiet bg-inverse text-fg-inverse [&_[data-slot=icon]]:text-icon-success [&_[data-slot=action]]:text-fg-inverse" },
      { theme: "dark", type: "warning", class: "skin-quiet bg-inverse text-fg-inverse [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=action]]:text-fg-inverse" },
      { theme: "dark", type: "error", class: "skin-quiet bg-inverse text-fg-inverse [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=action]]:text-fg-inverse" },
    ],
    defaultVariants: {
      theme: "light",
      type: "default",
    },
  },
);

const toastIcons = { default: Info, success: CircleCheck, warning: TriangleAlert, error: CircleAlert };

export interface ToastProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof toastVariants> {
  /** Button or link on the right, for example an Undo action. */
  action?: React.ReactNode;
}

const Toast = React.forwardRef<HTMLDivElement, ToastProps>(
  ({ className, theme, type, action, children, ...props }, ref) => {
    const Icon = toastIcons[type ?? "default"];
    return (
      <div data-slot="toast" data-kind="overlay" ref={ref} role="status" className={cn(toastVariants({ theme, type }), className)} {...props}>
        <Icon data-slot="icon" aria-hidden className="size-5 shrink-0" />
        <div className="min-w-0 flex-1">{children}</div>
        {action ? (
          <span data-slot="action" className="shrink-0 text-label-medium">
            {action}
          </span>
        ) : null}
      </div>
    );
  },
);
Toast.displayName = "Toast";

export { Toast, toastVariants };
